window.HOEREN_TESTS[7] = {"id":"urlaub-und-reisen-planen","name":"Urlaub und Reisen planen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist das Reisebüro Sonnenziel. Frau Hofer, Ihre Pauschalreise nach Mallorca ist bestätigt. Der Flug startet am Samstag um 7 Uhr 30 vom Flughafen München, nicht von Stuttgart wie ursprünglich geplant. Bitte seien Sie zwei Stunden vorher am Flughafen. Den Voucher schicken wir per E-Mail. Schöne Reise!","gender":"m","q":"Was hat sich an der Reise geändert?","opts":["Der Flughafen.","Die Uhrzeit.","Das Reiseziel."],"correct":0},{"transcript":"Achtung an die Reisenden auf Gleis 9. Der ICE 583 nach Hamburg hat heute zehn Minuten Verspätung wegen einer Türstörung. Reisende mit Anschluss in Hannover erreichen ihren Zug noch — der wartet auf uns. Wer nach Berlin weiterfährt, sollte einen anderen Anschluss am Hauptbahnhof Hamburg nehmen. Vielen Dank.","gender":"f","q":"Wer erreicht den Anschluss?","opts":["Niemand.","Reisende nach Berlin.","Reisende nach Hannover."],"correct":2},{"transcript":"Hallo Mama, hier ist Lukas. Wir kommen heute nicht mehr in München an, weil unser Auto eine Panne hatte. Wir übernachten in einem Hotel in Augsburg und fahren morgen früh weiter. Bitte mach dir keine Sorgen — uns geht es gut. Wir rufen morgen wieder an.","gender":"m","q":"Warum kommt Lukas heute nicht in München an?","opts":["Er ist krank.","Das Auto hatte eine Panne.","Das Hotel war voll."],"correct":1},{"transcript":"Liebe Hotelgäste, eine Information für Ihren Aufenthalt. Das Frühstück gibt es ab morgen erst um 8 Uhr statt um 7 Uhr — wegen einer Personalumstellung. Auch das Schwimmbad ist heute Nachmittag von 14 bis 17 Uhr geschlossen, eine Reinigungsarbeit. Wir entschuldigen uns für die Unannehmlichkeiten. Morgen ist alles wieder normal.","gender":"f","q":"Wann beginnt das Frühstück ab morgen?","opts":["Um 7 Uhr.","Um 8 Uhr.","Es fällt aus."],"correct":1},{"transcript":"Hi Sara, hier ist Anna. Also, wegen unserer Wanderung am Wochenende — das Wetter wird schlecht. Statt Samstag schlage ich Sonntag vor. Da wird es wieder sonnig. Wir können auch den Plan ändern und einfach nur zu Mittag essen, wenn dir Wandern bei Regen lieber wäre. Sag Bescheid bis Freitag.","gender":"f","q":"Was schlägt Anna vor?","opts":["Wandern am Samstag wie geplant.","Die Wanderung ganz absagen.","Die Wanderung auf Sonntag verschieben."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Petra","gender":"f","text":"Hallo Klaus! Unser Urlaub am See beginnt nächsten Samstag. Ich habe die Liste auf dem Tisch."},{"speaker":"Klaus","gender":"m","text":"Endlich geht es los, Petra. Sollen wir die Aufgaben vor der Abreise klar verteilen?"},{"speaker":"Petra","gender":"f","text":"Ich buche das Hotel heute Abend im Internet. Es ist ein kleines Haus am Wasser."},{"speaker":"Klaus","gender":"m","text":"Das Hotel kenne ich schon. Sollen wir unterwegs viele Fotos von der Reise machen?"},{"speaker":"Petra","gender":"f","text":"Nein. Fotos planen wir nicht extra. Dafür fehlt uns unterwegs die Ruhe."},{"speaker":"Klaus","gender":"m","text":"Ich fahre das Auto. Die Strecke dauert etwa vier Stunden."},{"speaker":"Petra","gender":"f","text":"Du kennst die Straße gut. Lisa plant die Tagesausflüge mit der großen Karte."},{"speaker":"Klaus","gender":"m","text":"Sie hat mir zwei Ideen genannt. Welche Ausflüge meint sie genau?"},{"speaker":"Petra","gender":"f","text":"Wir fahren zuerst zum Wasserfall und danach in die Altstadt. Eva bleibt meist im Haus."},{"speaker":"Klaus","gender":"m","text":"Eva kocht warmes Essen für uns. Suppe und Nudeln reichen ihr völlig."},{"speaker":"Petra","gender":"f","text":"Dann sparen wir uns das Restaurant. Sollen wir in jedem Laden Souvenirs für die Familie kaufen?"},{"speaker":"Klaus","gender":"m","text":"Souvenirs kaufen wir auch nicht. Der Koffer ist jetzt schon ziemlich voll."},{"speaker":"Petra","gender":"f","text":"Was passiert in der Zeit mit unserem Hund?"},{"speaker":"Klaus","gender":"m","text":"Tim kümmert sich um den Hund. Er bleibt die ganze Woche zu Hause."},{"speaker":"Petra","gender":"f","text":"Gut. Ich lege die Liste in die Reisetasche. Wir packen morgen Abend."}],"options":[{"letter":"a","text":"plant die Tagesausflüge"},{"letter":"b","text":"kümmert sich um den Hund"},{"letter":"c","text":"kauft Souvenirs"},{"letter":"d","text":"organisiert Karten für ein Konzert"},{"letter":"e","text":"bucht das Hotel"},{"letter":"f","text":"wäscht die Kleidung"},{"letter":"g","text":"macht die Fotos"},{"letter":"h","text":"fährt das Auto"},{"letter":"i","text":"kocht warmes Essen"}],"items":[{"person":"Petra","correct":"e"},{"person":"Klaus","correct":"h"},{"person":"Lisa","correct":"a"},{"person":"Eva","correct":"i"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Wohin möchten Sie reisen?"},{"speaker":"Kundin","gender":"f","text":"Wir hatten zwischen Spanien und Italien überlegt. Griechenland war zu teuer."},{"speaker":"Mitarbeiter","gender":"m","text":"Spanien ist im Juni günstiger. Italien dafür im Mai, aber Mai geht nicht."},{"speaker":"Kundin","gender":"f","text":"Wir fahren im Juni — also Spanien."},{"speaker":"Mitarbeiter","gender":"m","text":"Sehr gut. Ich zeige Ihnen Angebote für Spanien im Juni."},{"speaker":"Kundin","gender":"f","text":"Danke! Spanien im Juni, wir freuen uns schon!"}],"q":"Wohin reist die Kundin?","opts":["Nach Spanien.","Nach Italien.","Nach Griechenland."],"correct":0},{"lines":[{"speaker":"Rezeption","gender":"f","text":"Wie lange möchten Sie bleiben? Und wie viele Personen?"},{"speaker":"Gast","gender":"m","text":"Drei Nächte, ab Freitag. Zwei Personen, ohne Kinder."},{"speaker":"Rezeption","gender":"f","text":"Doppelzimmer oder Familienzimmer? Einzelzimmer haben wir auch frei."},{"speaker":"Gast","gender":"m","text":"Doppelzimmer reicht — meine Kinder kommen nicht mit. Kein Familienzimmer nötig."},{"speaker":"Rezeption","gender":"f","text":"Notiert. 360 Euro insgesamt. Möchten Sie mit Frühstück?"},{"speaker":"Gast","gender":"m","text":"Ja, mit Frühstück bitte! Dann bis Freitag, danke!"}],"q":"Welches Zimmer bekommt der Gast?","opts":["Einzelzimmer.","Doppelzimmer.","Familienzimmer."],"correct":1},{"lines":[{"speaker":"Reiseberater","gender":"m","text":"Welches Verkehrsmittel bevorzugen Sie?"},{"speaker":"Kundin","gender":"f","text":"Hmm. Auto wäre flexibel, aber die Strecke ist lang."},{"speaker":"Reiseberater","gender":"m","text":"Flug ist schneller und nicht viel teurer als Bahn."},{"speaker":"Kundin","gender":"f","text":"Dann nehme ich den Flug. Schneller ist mir wichtiger als flexibel."},{"speaker":"Reiseberater","gender":"m","text":"Gute Wahl! Soll ich gleich buchen? Der Flug geht täglich."},{"speaker":"Kundin","gender":"f","text":"Ja, bitte buchen! Vielen Dank und tschüss!"}],"q":"Wie reist die Kundin?","opts":["Mit dem Auto.","Mit dem Flugzeug.","Mit der Bahn."],"correct":1},{"lines":[{"speaker":"Reisende","gender":"f","text":"Mein Koffer ist nicht angekommen!"},{"speaker":"Mitarbeiterin","gender":"f","text":"Aus welcher Stadt sind Sie gekommen?"},{"speaker":"Reisende","gender":"f","text":"Berlin. Flug LH 254."},{"speaker":"Mitarbeiterin","gender":"f","text":"Moment, ich prüfe. Ja, Ihr Koffer ist noch in Frankfurt. Wir bringen ihn morgen zu Ihrem Hotel."},{"speaker":"Reisende","gender":"f","text":"Danke! Wann kommt er genau? Morgen früh?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Morgen früh um neun, direkt zu Ihrem Hotel. Entschuldigung!"}],"q":"Wo ist der Koffer?","opts":["In Berlin.","Schon im Hotel.","In Frankfurt."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Können wir die Reise stornieren?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Sie wollten in zwei Wochen abreisen, oder?"},{"speaker":"Kundin","gender":"f","text":"Genau, mein Mann ist plötzlich krank geworden."},{"speaker":"Mitarbeiterin","gender":"f","text":"Mit Krankheits-Schein bekommen Sie 90 Prozent zurück. Ohne Schein nur 50. Ganz ohne Grund gäbe es nichts zurück."},{"speaker":"Kundin","gender":"f","text":"Ein Schein ist kein Problem. Ich bringe ihn morgen vorbei."},{"speaker":"Mitarbeiterin","gender":"f","text":"Perfekt! Dann bekommen Sie 90 Prozent zurück. Bis morgen!"}],"q":"Wie viel bekommt die Kundin zurück?","opts":["50 Prozent.","Nichts.","90 Prozent."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Lange, einem Reiseleiter. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Lange, Sie sind Reiseleiter seit 15 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Lange","gender":"m","text":"Eigentlich bin ich Geschichtslehrer von Beruf. Aber während meiner ersten Reise nach Italien habe ich gemerkt, wie sehr ich es genieße, anderen Menschen fremde Orte zu zeigen. Nach zwei Jahren Schule habe ich umgesattelt."},{"speaker":"Reporter","gender":"m","text":"Welche Länder bereisen Sie am meisten?"},{"speaker":"Lange","gender":"m","text":"Italien und Griechenland — das sind meine Spezialgebiete. In Spanien war ich auch ein paar Mal, aber da kenne ich mich nicht so gut aus. Asien fahre ich nie, das machen andere Kollegen."},{"speaker":"Reporter","gender":"m","text":"Wie sind die Gruppen?"},{"speaker":"Lange","gender":"m","text":"Meist zwischen 15 und 30 Personen. Junge und alte Reisende mischen sich. Das ist meist sehr nett, manchmal aber auch schwierig — wenn jemand ungeduldig ist oder zu spät kommt."},{"speaker":"Reporter","gender":"m","text":"Was war Ihre schwierigste Reise?"},{"speaker":"Lange","gender":"m","text":"Eine Gruppe in Sizilien, wo wir einen kleinen Unfall mit dem Bus hatten. Niemand wurde verletzt, aber wir mussten zwei Tage im Hotel warten. Die Reisenden waren erst sauer, aber am Ende haben sie es gut genommen."},{"speaker":"Reporter","gender":"m","text":"Reisen Sie selbst auch in Ihrem Urlaub?"},{"speaker":"Lange","gender":"m","text":"Sehr wenig. Ich bin das ganze Jahr unterwegs — im Urlaub bleibe ich zu Hause. Mein Garten ist mein Ferienort. Manchmal fahre ich kurz ans Meer, aber nicht weit."}],"items":[{"q":"Herr Lange war früher Lehrer.","correct":"ja"},{"q":"Er führt Reisegruppen nach Asien.","correct":"nein"},{"q":"In einer schwierigen Reise war ein Busunfall.","correct":"ja"},{"q":"Niemand wurde bei dem Unfall verletzt.","correct":"ja"},{"q":"Im Urlaub reist er gern weit weg.","correct":"nein"}]}]};
